/// To implement a server, implement an object which conforms to this protocol.
@available(macOS 10.15, iOS 13, tvOS 13, watchOS 6, *)
internal protocol NymVpnService_NymVpnServiceAsyncProvider: CallHandlerProvider, Sendable {
  static var serviceDescriptor: GRPCServiceDescriptor { get }
  var interceptors: NymVpnService_NymVpnServiceServerInterceptorFactoryProtocol? { get }

  /// Get info regarding the nym-vpnd in general, like version etc.
  func info(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> NymVpnService_InfoResponse

  /// Set the network. This requires a restart to take effect
  func setNetwork(
    request: SwiftProtobuf.Google_Protobuf_StringValue,
    context: GRPCAsyncServerCallContext
  ) async throws -> SwiftProtobuf.Google_Protobuf_Empty

  /// List messages fetched from nym-vpn-api
  func getSystemMessages(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> NymVpnService_GetSystemMessagesResponse

  /// List network compatibility client versions from nym-vpn-api
  func getNetworkCompatibility(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> NymVpnService_GetNetworkCompatibilityResponse

  /// List the feature flags fetched from the nym-vpn-api
  func getFeatureFlags(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> NymVpnService_GetFeatureFlagsResponse

  /// Connect the tunnel
  func connectTunnel(
    request: NymVpnService_ConnectRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> SwiftProtobuf.Google_Protobuf_Empty

  /// Disconnect the tunnel
  func disconnectTunnel(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> SwiftProtobuf.Google_Protobuf_Empty

  /// Get the current tunnel state
  func getTunnelState(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> NymVpnService_TunnelState

  /// Listen for current tunnel state and subsequent changes to it. Emits current state as the first value.
  func listenToTunnelState(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    responseStream: GRPCAsyncResponseStreamWriter<NymVpnService_TunnelState>,
    context: GRPCAsyncServerCallContext
  ) async throws

  //// Listen for daemon events.
  func listenToEvents(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    responseStream: GRPCAsyncResponseStreamWriter<NymVpnService_TunnelEvent>,
    context: GRPCAsyncServerCallContext
  ) async throws

  /// List the available gateways for the selected mode
  func listGateways(
    request: NymVpnService_ListGatewaysRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> NymVpnService_ListGatewaysResponse

  /// List the available countries for the selected mode
  func listCountries(
    request: NymVpnService_ListCountriesRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> NymVpnService_ListCountriesResponse

  /// Store the recovery phrase, which is also the account identity and authentication
  func storeAccount(
    request: NymVpnService_StoreAccountRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> NymVpnService_AccountCommandResponse

  /// Check if the recovery phrase is stored
  func isAccountStored(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> SwiftProtobuf.Google_Protobuf_BoolValue

  /// Removes everything related to the account, including the device identity,
  /// credential storage, mixnet keys, gateway registrations.
  func forgetAccount(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> NymVpnService_AccountCommandResponse

  /// Get the account identity of the locally stored recovery phrase
  func getAccountIdentity(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> NymVpnService_GetAccountIdentityResponse

  /// Get the set of account links for the user
  func getAccountLinks(
    request: NymVpnService_GetAccountLinksRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> NymVpnService_AccountManagement

  /// Query the account state, which is synced from the nym-vpn-api account, as it
  /// is known and interpreted by nym-vpnd
  func getAccountState(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> NymVpnService_AccountControllerState

  /// Listen for current account controller state and subsequent changes to it. Emits current state as the first value.
  func listenToAccountState(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    responseStream: GRPCAsyncResponseStreamWriter<NymVpnService_AccountControllerState>,
    context: GRPCAsyncServerCallContext
  ) async throws

  /// The vpn client will periodically refresh the account state in the
  /// background. This command triggers a manual refresh.
  func refreshAccountState(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> SwiftProtobuf.Google_Protobuf_Empty

  /// Get the account usage from the nym-vpn-api
  func getAccountUsage(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> NymVpnService_GetAccountUsageResponse

  /// Reset the device identity
  func resetDeviceIdentity(
    request: NymVpnService_ResetDeviceIdentityRequest,
    context: GRPCAsyncServerCallContext
  ) async throws -> SwiftProtobuf.Google_Protobuf_Empty

  /// Get the device identity
  func getDeviceIdentity(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> NymVpnService_GetDeviceIdentityResponse

  /// Get the list of devices associated with this account from the nym-vpn-api
  func getDevices(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> NymVpnService_GetDevicesResponse

  /// Get the list of active devices associated with this account from the nym-vpn-api
  func getActiveDevices(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> NymVpnService_GetDevicesResponse

  /// Get the available tickets in the local credential store
  func getAvailableTickets(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> NymVpnService_AvailableTickets

  /// Get the log file path
  func getLogPath(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> NymVpnService_GetLogPathResponse

  /// Delete the log file
  func deleteLogFile(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> SwiftProtobuf.Google_Protobuf_Empty

  /// Check if Sentry error monitoring is enabled
  func isSentryEnabled(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> SwiftProtobuf.Google_Protobuf_BoolValue

  /// Enable Sentry error monitoring (requires daemon restart)
  func enableSentry(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> SwiftProtobuf.Google_Protobuf_Empty

  /// Disable Sentry error monitoring (requires daemon restart)
  func disableSentry(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> SwiftProtobuf.Google_Protobuf_Empty

  /// Check if network statistics collection is enabled
  func isCollectNetworkStatsEnabled(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> SwiftProtobuf.Google_Protobuf_BoolValue

  /// Enable network statistics collection (requires daemon restart)
  func enableCollectNetworkStats(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> SwiftProtobuf.Google_Protobuf_Empty

  /// Disable network statistics collection (requires daemon restart)
  func disableCollectNetworkStats(
    request: SwiftProtobuf.Google_Protobuf_Empty,
    context: GRPCAsyncServerCallContext
  ) async throws -> SwiftProtobuf.Google_Protobuf_Empty
}

